    transcodeResourceAudio: {
        parameters: {
            query?: {
                /** @description 从原片多少秒开始转码。前端 seek 后应使用当前 video.currentTime 重新请求。 */
                start?: number;
                /** @description 音轨序号，按 ffmpeg 的音频流相对序号计算，0 表示第一条音轨。 */
                audio_track?: number;
                /** @description 输出音频格式。默认 mp3 优先保证 HTML audio 兼容性；aac 输出 ADTS AAC。 */
                format?: "mp3" | "aac";
                /** @description 前端播放会话 ID。强烈建议每个播放器实例生成并复用；同一资源同一 session_id 的新转码请求会先停止旧转码进程。 */
                session_id?: string;
            };
            header?: never;
            path: {
                id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description 实时音频转码流 */
            200: {
                headers: {
                    /** @description 本次转码请求的原片起始秒数。 */
                    "X-Cyber-Audio-Start"?: string;
                    /** @description 本次转码使用的音轨序号。 */
                    "X-Cyber-Audio-Track"?: string;
                    /** @description 本次转码输出格式。 */
                    "X-Cyber-Audio-Format"?: string;
                    /** @description 本次转码所属播放会话 ID。 */
                    "X-Cyber-Playback-Session"?: string;
                    /** @description 后端历史心跳兜底超时时间，单位秒。超过该时间未收到对应资源的播放进度提交时会停止转码。 */
                    "X-Cyber-History-Timeout"?: string;
                    [name: string]: unknown;
                };
                content: {
                    "audio/mpeg": string;
                    "audio/aac": string;
                };
            };
            /** @description 请求参数错误，或存储源不支持 ffmpeg 输入。 */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description 资源不存在。 */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description 并发音频转码数已满，前端应稍后重试。 */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description ffmpeg 不可用。 */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
